"""SQLAlchemy model of a slide-1 cover generated by Grok from library photos."""

from __future__ import annotations

import uuid
from datetime import datetime

from sqlalchemy import DateTime, Float, ForeignKey, Index, Integer, String
from sqlalchemy.orm import Mapped, mapped_column
from sqlalchemy.sql import func

from rag_backend.domain.constants.cover_generation import (
    ERROR_CODE_LENGTH,
    INDEX_COVER_GENERATIONS_OWNER_CREATED,
    INDEX_COVER_GENERATIONS_PROJECT,
    MODEL_LENGTH,
    PROMPT_SHA256_LENGTH,
    STATUS_LENGTH,
    TABLE_COVER_GENERATIONS,
)
from rag_backend.domain.models.cover_generation import (
    CoverGeneration,
    CoverGenerationStatus,
)
from rag_backend.infrastructure.database.config import Base


class CarouselCoverGenerationModel(Base):
    """One generation: the budget log row and its outcome.

    The carousel and the result asset are kept with ``SET NULL``, so deleting
    either never erases the spend record (the monthly cap still counts it);
    deleting the owner removes it.
    """

    __tablename__ = TABLE_COVER_GENERATIONS

    id: Mapped[str] = mapped_column(
        String(36), primary_key=True, default=lambda: str(uuid.uuid4())
    )
    project_id: Mapped[str | None] = mapped_column(
        String(36),
        ForeignKey("carousel_projects.id", ondelete="SET NULL"),
        nullable=True,
    )
    owner_id: Mapped[str] = mapped_column(
        String(36), ForeignKey("users.id", ondelete="CASCADE"), nullable=False
    )
    status: Mapped[str] = mapped_column(String(STATUS_LENGTH), nullable=False)
    prompt_sha256: Mapped[str] = mapped_column(
        String(PROMPT_SHA256_LENGTH), nullable=False
    )
    photo_count: Mapped[int] = mapped_column(Integer, nullable=False)
    model: Mapped[str] = mapped_column(String(MODEL_LENGTH), nullable=False)
    cost_usd: Mapped[float] = mapped_column(Float, nullable=False)
    result_asset_id: Mapped[str | None] = mapped_column(
        String(36),
        ForeignKey("carousel_creator_assets.id", ondelete="SET NULL"),
        nullable=True,
    )
    error_code: Mapped[str | None] = mapped_column(
        String(ERROR_CODE_LENGTH), nullable=True
    )
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=func.now()
    )
    completed_at: Mapped[datetime | None] = mapped_column(
        DateTime(timezone=True), nullable=True
    )

    __table_args__ = (
        Index(INDEX_COVER_GENERATIONS_PROJECT, "project_id"),
        Index(INDEX_COVER_GENERATIONS_OWNER_CREATED, "owner_id", "created_at"),
    )

    def to_entity(self) -> CoverGeneration:
        """The domain row."""
        return CoverGeneration(
            id=uuid.UUID(self.id),
            project_id=self.project_id or "",
            owner_id=self.owner_id,
            status=CoverGenerationStatus(self.status),
            prompt_sha256=self.prompt_sha256,
            photo_count=self.photo_count,
            model=self.model,
            cost_usd=self.cost_usd,
            created_at=self.created_at,
            completed_at=self.completed_at,
            result_asset_id=(
                uuid.UUID(self.result_asset_id) if self.result_asset_id else None
            ),
            error_code=self.error_code,
        )

    @classmethod
    def from_entity(cls, entity: CoverGeneration) -> CarouselCoverGenerationModel:
        """A new row for ``entity``."""
        return cls(
            id=str(entity.id),
            project_id=entity.project_id,
            owner_id=entity.owner_id,
            status=entity.status.value,
            prompt_sha256=entity.prompt_sha256,
            photo_count=entity.photo_count,
            model=entity.model,
            cost_usd=entity.cost_usd,
            created_at=entity.created_at,
            completed_at=entity.completed_at,
            result_asset_id=(
                str(entity.result_asset_id) if entity.result_asset_id else None
            ),
            error_code=entity.error_code,
        )
